        "explanation": "Diễn ngôn tinh hoa bản ngữ C2: Epistemology: Truth & Knowledge. Dạng khẳng định dùng để diễn đạt sự thật, thói quen hoặc thông tin cơ bản liên quan đến \"Epistemology: Truth & Knowledge\".",
        "examples": "[{\"en\":\"I use \\\"Epistemology\\\" regularly when communicating with others.\",\"vi\":\"Tôi sử dụng từ \\\"Epistemology\\\" thường xuyên khi giao tiếp với mọi người.\"},{\"en\":\"She practices \\\"Justification\\\" every morning to improve her skills.\",\"vi\":\"Cô ấy luyện tập \\\"Justification\\\" mỗi sáng để nâng cao kỹ năng của mình.\"},{\"en\":\"We understand the importance of \\\"Empiricism\\\" in real-life contexts.\",\"vi\":\"Chúng tôi thấu hiểu tầm quan trọng của \\\"Empiricism\\\" trong các ngữ cảnh đời thực.\"}]"
