        "explanation": "Khi muốn phủ định hoặc đặt câu hỏi về chủ đề Epistemology: Truth & Knowledge, hãy sử dụng trợ động từ phù hợp với chủ ngữ. Động từ chính luôn quay về dạng nguyên mẫu.",
        "examples": "[{\"en\":\"I do not forget to practice \\\"Epistemology\\\" every single day.\",\"vi\":\"Tôi không quên luyện tập \\\"Epistemology\\\" mỗi ngày.\"},{\"en\":\"Does he know how to apply \\\"Justification\\\" correctly?\",\"vi\":\"Cậu ấy có biết cách áp dụng \\\"Justification\\\" một cách chính xác không?\"},{\"en\":\"They do not have any difficulty with \\\"Empiricism\\\".\",\"vi\":\"Họ không gặp bất kỳ khó khăn nào với \\\"Empiricism\\\".\"}]"
