        "explanation": "Diễn ngôn tinh hoa bản ngữ C2: Native Idiomacity & Vernacular Nuances. Dạng khẳng định dùng để diễn đạt sự thật, thói quen hoặc thông tin cơ bản liên quan đến \"Native Idiomacity & Vernacular Nuances\".",
        "examples": "[{\"en\":\"I use \\\"Beyond the pale\\\" regularly when communicating with others.\",\"vi\":\"Tôi sử dụng từ \\\"Beyond the pale\\\" thường xuyên khi giao tiếp với mọi người.\"},{\"en\":\"She practices \\\"Fly in the ointment\\\" every morning to improve her skills.\",\"vi\":\"Cô ấy luyện tập \\\"Fly in the ointment\\\" mỗi sáng để nâng cao kỹ năng của mình.\"},{\"en\":\"We understand the importance of \\\"Bite the dust\\\" in real-life contexts.\",\"vi\":\"Chúng tôi thấu hiểu tầm quan trọng của \\\"Bite the dust\\\" trong các ngữ cảnh đời thực.\"}]"
