        "examples": "[{\"en\":\"I use \\\"Prosody\\\" regularly when communicating with others.\",\"vi\":\"Tôi sử dụng từ \\\"Prosody\\\" thường xuyên khi giao tiếp với mọi người.\"},{\"en\":\"She practices \\\"Modulation\\\" every morning to improve her skills.\",\"vi\":\"Cô ấy luyện tập \\\"Modulation\\\" mỗi sáng để nâng cao kỹ năng của mình.\"},{\"en\":\"We understand the importance of \\\"Pitch\\\" in real-life contexts.\",\"vi\":\"Chúng tôi thấu hiểu tầm quan trọng của \\\"Pitch\\\" trong các ngữ cảnh đời thực.\"}]"
