        "explanation": "Diễn ngôn tinh hoa bản ngữ C2: Publishing Stylistic Identity in Global Journals. Dạng khẳng định dùng để diễn đạt sự thật, thói quen hoặc thông tin cơ bản liên quan đến \"Publishing Stylistic Identity in Global Journals\".",
        "examples": "[{\"en\":\"I use \\\"Voice\\\" regularly when communicating with others.\",\"vi\":\"Tôi sử dụng từ \\\"Voice\\\" thường xuyên khi giao tiếp với mọi người.\"},{\"en\":\"She practices \\\"Journal\\\" every morning to improve her skills.\",\"vi\":\"Cô ấy luyện tập \\\"Journal\\\" mỗi sáng để nâng cao kỹ năng của mình.\"},{\"en\":\"We understand the importance of \\\"Stylistic identity\\\" in real-life contexts.\",\"vi\":\"Chúng tôi thấu hiểu tầm quan trọng của \\\"Stylistic identity\\\" trong các ngữ cảnh đời thực.\"}]"
