        "examples": "[{\"en\":\"I do not forget to practice \\\"Voice\\\" every single day.\",\"vi\":\"Tôi không quên luyện tập \\\"Voice\\\" mỗi ngày.\"},{\"en\":\"Does he know how to apply \\\"Journal\\\" correctly?\",\"vi\":\"Cậu ấy có biết cách áp dụng \\\"Journal\\\" một cách chính xác không?\"},{\"en\":\"They do not have any difficulty with \\\"Stylistic identity\\\".\",\"vi\":\"Họ không gặp bất kỳ khó khăn nào với \\\"Stylistic identity\\\".\"}]"
