        "explanation": "Diễn ngôn tinh hoa bản ngữ C2: Deciphering Cryptic English & Ambiguity. Dạng khẳng định dùng để diễn đạt sự thật, thói quen hoặc thông tin cơ bản liên quan đến \"Deciphering Cryptic English & Ambiguity\".",
        "examples": "[{\"en\":\"I use \\\"Cryptic\\\" regularly when communicating with others.\",\"vi\":\"Tôi sử dụng từ \\\"Cryptic\\\" thường xuyên khi giao tiếp với mọi người.\"},{\"en\":\"She practices \\\"Ambiguity\\\" every morning to improve her skills.\",\"vi\":\"Cô ấy luyện tập \\\"Ambiguity\\\" mỗi sáng để nâng cao kỹ năng của mình.\"},{\"en\":\"We understand the importance of \\\"Polysemy\\\" in real-life contexts.\",\"vi\":\"Chúng tôi thấu hiểu tầm quan trọng của \\\"Polysemy\\\" trong các ngữ cảnh đời thực.\"}]"
