        "examples": "[{\"en\":\"I do not forget to practice \\\"Cryptic\\\" every single day.\",\"vi\":\"Tôi không quên luyện tập \\\"Cryptic\\\" mỗi ngày.\"},{\"en\":\"Does he know how to apply \\\"Ambiguity\\\" correctly?\",\"vi\":\"Cậu ấy có biết cách áp dụng \\\"Ambiguity\\\" một cách chính xác không?\"},{\"en\":\"They do not have any difficulty with \\\"Polysemy\\\".\",\"vi\":\"Họ không gặp bất kỳ khó khăn nào với \\\"Polysemy\\\".\"}]"
